def split_row(line: str):
    """Split one CSV line into fields. Fields may be double-quoted; inside a
    quoted field a comma is literal and a doubled quote is a literal quote.
    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        char = line[i]
        if in_quotes:
            if char == '"':
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                current.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append("".join(current))
                current = []
            else:
                current.append(char)
        i += 1

    fields.append("".join(current))
    return fields

